// The voice strip above the prompt: what parlard is doing, the last line heard or spoken, and
// buttons for mute, voice, stop and focus. /parlar (or the strip's pane button) opens the voice
// pane: the conversation so far, the sessions to talk to, and the mic and speaker. It follows `parlar ctl watch` and draws nothing while
// the conversation is off or parlard is not running. The command hooks in hooks.json carry the
// conversation itself; this module only shows it.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Device, HistoryLine, Panel, Phase, Rows, Section, SessionRow, Strip } from '../types'
import { AGENT, registerRows, USER, withNote } from './rows'

const IDLE: Strip = {
  connected: false,
  phase: 'stopped',
  muted: false,
  voiceOff: false,
  focused: false,
  levels: [],
  caption: null,
  flare: false,
}
const strip = atom({ plugin: 'parlar', key: 'strip' } as const, IDLE)
// the rows rows.tsx draws; the strip adds parlar's notes, which only the watch stream carries
const rows = atom({ plugin: 'parlar', key: 'rows' } as const, { wakes: {}, calls: {} } as Rows)
const panel = atom(
  { plugin: 'parlar', key: 'panel' } as const,
  { history: [], sessions: [], devices: null } as Panel,
)

const PANE = 'parlar'
// lines the pane keeps, and devices it lists per kind
const HISTORY = 200
const DEVICES = 6

const BARS = '▁▂▃▄▅▆▇█'
const METER = 8
// level events come at 30 Hz; the terminal redraws at this pace at most
const FRAME_MS = 125
const CAPTION_MS = 15_000
// the longest phase word ('connecting'), so the line does not shift between phases
const WORD_WIDTH = 10
// cells of the strip's fixed parts: '● voice ' and the padded word, then each label and button
// as the terminal draws it ('m: mute'), each with the gap before it
const CELLS = {
  phase: 8 + 10,
  caption: 1,
  meter: 1 + 8,
  notFocused: 1 + 16,
  captionsOnly: 1 + 13,
  talk: 1 + 12,
  mute: 1 + 9,
  voice: 1 + 12,
  stop: 1 + 7,
  pane: 1 + 13,
}

/** What fits in `width`: mute and stop always (and talk here off focus), the rest by priority. */
export function fits(width: number, s: { focused: boolean; voiceOff: boolean }, metering: boolean) {
  // the caption box is always in the row, so its gap is too; the button group's leading gap is
  // the one its first button counts
  let left = width - CELLS.phase - CELLS.caption - CELLS.mute - CELLS.stop - (s.focused ? 0 : CELLS.talk)
  const take = (want: boolean, cells: number) => {
    if (!want || left < cells) return false
    left -= cells
    return true
  }
  const meter = take(metering, CELLS.meter)
  const voice = take(true, CELLS.voice)
  const notFocused = take(!s.focused, CELLS.notFocused)
  const captionsOnly = take(s.voiceOff, CELLS.captionsOnly)
  const pane = take(true, CELLS.pane)
  return { meter, voice, notFocused, captionsOnly, pane }
}
const FLARE_MS = 1_200

// the phases in which someone is talking: the strip takes its own line only then
const TALKING: ReadonlySet<Phase> = new Set(['listening', 'interrupting', 'speaking'])

const WORDS: Record<Phase, string> = {
  stopped: 'off',
  connecting: 'connecting',
  ready: 'ready',
  listening: 'listening',
  interrupting: 'listening',
  working: 'working',
  speaking: 'speaking',
}

type Event =
  | { ui: 'phase'; phase: Phase; mic_muted: boolean; voice_off: boolean }
  | { ui: 'levels'; user: number; agent: number }
  | { ui: 'tool'; ok: boolean; name: string | null }
  | { ui: 'caption'; who: string; text: string; session?: string; partial?: boolean; call?: string }
  | { ui: 'notice'; text: string }

export const meter = (levels: readonly number[]) =>
  levels
    .map(l => BARS[Math.min(BARS.length - 1, Math.floor(Math.sqrt(Math.max(0, l)) * BARS.length))])
    .join('')

// the module's own values: a reload starts them over, the strip itself lives in $.state
const live = {
  // the plugin's launcher, which finds parlar the way the command hooks do (PARLAR_BIN, the user
  // install directories, npm); plain `parlar` from PATH where the launcher is a .cmd (Windows)
  bin: 'parlar',
  watching: false,
  session: '',
  phase: 'stopped' as Phase,
  levels: [] as number[],
  dirty: false,
  captionAt: 0,
  flareAt: 0,
  // set once the watch has seen parlard, so the first connect of a session raises no toast
  seen: false,
}

function set($: EngineInterface, patch: Partial<Strip>) {
  return update($, strip, s => ({ ...s, ...patch }))
}

async function ctl($: EngineInterface, ...args: string[]) {
  await $.process.run([live.bin, 'ctl', ...args], { timeoutMs: 5_000 }).catch(() => undefined)
}

async function refreshFocus($: EngineInterface) {
  const r = await $.process.run([live.bin, 'ctl', 'state'], { timeoutMs: 2_000 }).catch(() => undefined)
  if (!r || r.exitCode !== 0) return
  try {
    const st = JSON.parse(r.stdout) as { sessions?: Partial<SessionRow>[] }
    const sessions = (st.sessions ?? []).flatMap(s =>
      s.session
        ? [{ session: s.session, cwd: s.cwd ?? '', harness: s.harness ?? '', focused: s.focused === true }]
        : [],
    )
    const focused = sessions.some(s => s.session === live.session && s.focused)
    const was = await read($, strip)
    if (focused !== was.focused) {
      await set($, { focused })
      // typing elsewhere moves the voice without a sound here; say where it went
      const to = sessions.find(s => s.focused)
      if (was.focused && to && was.phase !== 'stopped') $.ui.toast(`Voice moved to ${folder(to.cwd)}`)
    }
    if (JSON.stringify(sessions) !== JSON.stringify((await read($, panel)).sessions)) {
      await update($, panel, p => ({ ...p, sessions }))
    }
  } catch {
    // a daemon mid-restart can answer half a line; the next poll reads it again
  }
}

async function apply($: EngineInterface, ev: Event, now: number) {
  switch (ev.ui) {
    case 'phase': {
      const back = live.seen && !(await read($, strip)).connected && ev.phase !== 'stopped'
      live.seen = true
      if (back) $.ui.toast('parlard is back')
      live.phase = ev.phase
      live.levels = []
      await set($, {
        connected: true,
        phase: ev.phase,
        muted: ev.mic_muted,
        voiceOff: ev.voice_off,
        levels: [],
      })
      void refreshFocus($).catch(quiet)
      return
    }
    case 'levels': {
      const phase = live.phase
      const l =
        phase === 'speaking' ? ev.agent : phase === 'listening' || phase === 'interrupting' ? ev.user : 0
      live.levels = [...live.levels, l].slice(-METER)
      live.dirty = true
      return
    }
    case 'tool':
      if (!ev.ok) {
        live.flareAt = now
        await set($, { flare: true })
      }
      return
    case 'notice':
      $.ui.toast(ev.text, { timeoutMs: 12_000 })
      return
    case 'caption': {
      // a caption names its session; a partial, parlar's own line, or a daemon from before that
      // field belongs to whoever has focus
      const mine = ev.session !== undefined ? ev.session === live.session : (await read($, strip)).focused
      if (!mine) return
      live.captionAt = now
      await set($, { caption: { who: ev.who, text: ev.text } })
      // parlar's answer during a long tool call is drawn on that call's row
      if (ev.call) {
        const call = ev.call
        await update($, rows, r => withNote(r, call, ev.text))
      }
      // the pane keeps finished lines, not the words so far
      if (ev.partial) return
      const line: HistoryLine = { who: ev.who === 'user' ? 'you' : 'parlar', text: ev.text }
      await update($, panel, p => ({ ...p, history: [...p.history, line].slice(-HISTORY) }))
      void toLatest($).catch(quiet)
      return
    }
  }
}

async function watch($: EngineInterface) {
  live.watching = true
  let buf = ''
  try {
    for await (const { stream, text } of $.process.spawn({ argv: [live.bin, 'ctl', 'watch'] })) {
      if (stream !== 'stdout') continue
      buf += text
      let nl: number
      while ((nl = buf.indexOf('\n')) >= 0) {
        const line = buf.slice(0, nl)
        buf = buf.slice(nl + 1)
        try {
          await apply($, JSON.parse(line) as Event, await $.clock.now())
        } catch {
          // an event kind this build does not know yet
        }
      }
    }
  } catch {
    // parlar is not on PATH: stay quiet, as the command hooks do
  } finally {
    live.watching = false
    const was = await read($, strip)
    await set($, { connected: false, levels: [] })
    // the watch also ends when the module unloads; only a parlard that no longer answers is news
    if (was.connected && was.phase !== 'stopped' && !(await answers($))) {
      $.ui.toast('parlard stopped: voice is off until it is back', { timeoutMs: 8_000 })
    }
  }
}

async function answers($: EngineInterface) {
  const r = await $.process.run([live.bin, 'ctl', 'state'], { timeoutMs: 2_000 }).catch(() => undefined)
  return r?.exitCode === 0
}

// a timer that fires as the module unloads finds $ gone; the next load starts its own
function quiet() {}

async function frame($: EngineInterface) {
  const now = await $.clock.now()
  const s = await read($, strip)
  const patch: Partial<Strip> = {}
  if (live.dirty) {
    live.dirty = false
    patch.levels = live.levels
  }
  if (s.caption && now - live.captionAt > CAPTION_MS) patch.caption = null
  if (s.flare && now - live.flareAt > FLARE_MS) patch.flare = false
  if (Object.keys(patch).length > 0) await set($, patch)
}

async function refreshDevices($: EngineInterface) {
  const r = await $.process.run([live.bin, 'ctl', 'devices'], { timeoutMs: 5_000 }).catch(() => undefined)
  if (!r || r.exitCode !== 0) return
  try {
    const d = JSON.parse(r.stdout) as { inputs?: Device[]; outputs?: Device[] }
    await update($, panel, p => ({ ...p, devices: { inputs: d.inputs ?? [], outputs: d.outputs ?? [] } }))
  } catch {
    // an answer this build cannot read leaves the pickers as they were
  }
}

async function openPane($: EngineInterface) {
  await set($, { paneOpen: true })
  const placed = await $.ui.open({ id: PANE, title: 'Voice' })
  await Promise.all([refreshFocus($), refreshDevices($)])
  await toLatest($)
  return placed
}

/** The pane opens on, and follows, the newest line of the conversation. */
async function toLatest($: EngineInterface) {
  if (!(await read($, strip)).paneOpen) return
  await $.ui.scroll({ in: PANE, to: 'end' }).catch(quiet)
}

/** The pane button: opens the pane, or closes it when it is open. */
async function togglePane($: EngineInterface) {
  // kept in $.state, so a reload of the module still knows the pane is open
  if (!(await read($, strip)).paneOpen) return void (await openPane($))
  await set($, { paneOpen: false })
  await $.ui.close({ id: PANE })
}

async function pickDevice($: EngineInterface, kind: 'input' | 'output', id: string) {
  await ctl($, kind, id)
  await update($, panel, p => ({ ...p, open: null }))
  await refreshDevices($)
}

/** Give a session voice focus from the pane; this one is attached first if parlard lacks it. */
async function talkTo($: EngineInterface, session: string, here: boolean) {
  await (here ? ctl($, 'talk', '--session', session) : ctl($, 'focus', session))
  await update($, panel, p => ({ ...p, open: null }))
  await refreshFocus($)
}

function folder(cwd: string) {
  return cwd.split(/[\\/]/).filter(Boolean).pop() ?? cwd
}

async function pollFocus($: EngineInterface) {
  const s = await read($, strip)
  if (s.connected && s.phase !== 'stopped') await refreshFocus($)
}

export const register: Register = on => {
  registerRows(on)
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    if (!e.isInteractive) return started
    // the hooks started from now on leave the heard and spoken lines to rows.tsx
    await $.env.set('PARLAR_ROWS', '1')
    live.session = await $.session.id()
    const root = $.plugin.root
    live.bin = root.includes('\\') ? 'parlar' : `${root}/bin/parlar`
    // a reload starts the strip over, but a pane it opened is still open
    await update($, strip, old => ({ ...IDLE, paneOpen: old.paneOpen }))
    void watch($).catch(quiet)
    // reconnect after parlard starts or restarts
    $.clock.every(5_000, () => {
      if (!live.watching) void watch($).catch(quiet)
    })
    $.clock.every(FRAME_MS, () => void frame($).catch(quiet))
    // focus moves with typing in another session, which sends no event here
    $.clock.every(2_000, () => void pollFocus($).catch(quiet))
    await $.command.register({
      name: 'parlar',
      description: 'Open the voice pane: the conversation, the sessions, the mic and speaker',
      immediate: true,
    })
    return started
  })

  // closed by the person (its mark, Esc) or an unload: the button opens it next time
  on('ui.close', async ($, e, next) => {
    const closed = await next(e)
    if (e.id === PANE) {
      await set($, { paneOpen: false })
    }
    return closed
  })

  on('command.run', { command: 'parlar' }, async $ => {
    const { isPlaced } = await openPane($)
    return { text: isPlaced ? 'Voice pane opened.' : 'The voice pane will open when there is room.' }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Button, Text } = $.ui.resolve(e)
    const s = await read($, strip)
    const p = await read($, panel)
    const others = p.sessions.filter(x => x.session !== live.session)
    const here = p.sessions.find(x => x.session === live.session)
    const word = !s.connected ? 'parlard is not running' : s.muted ? 'mic muted' : WORDS[s.phase]
    const focusedName = p.sessions.find(x => x.focused)
    const conversing = s.connected && s.phase !== 'stopped'
    // plain ALSA lists one card many times: one entry per name, the current one first
    const named = (list: Device[]) => {
      const one = list.filter((d, i) => d.current || list.findIndex(x => x.name === d.name) === i)
      return [...one.filter(d => d.current), ...one.filter(d => !d.current)].slice(0, DEVICES)
    }
    const inputs = named(p.devices?.inputs ?? [])
    const outputs = named(p.devices?.outputs ?? [])
    const current = (list: Device[]) => list.find(d => d.current)?.name ?? 'none'
    // one line per section until clicked open; picking closes it again
    const header = (key: Section, title: string, value: string) => (
      <Button
        key={`open-${key}`}
        label={`${p.open === key ? '▾' : '▸'} ${title}: ${value}`}
        plain
        onPress={() => update($, panel, x => ({ ...x, open: x.open === key ? null : key }))}
      />
    )
    const pick = (kind: 'input' | 'output', d: Device) =>
      d.current ? (
        <Text> ● {d.name}</Text>
      ) : (
        <Button
          key={`${kind}-${d.id}`}
          label={`  ○ ${d.name}`}
          plain
          onPress={() => pickDevice($, kind, d.id)}
        />
      )
    return (
      <Box flexDirection="column">
        {/* the one place with every control in every state (idle, muted, stopped), on the
            status line itself so the pane stays the conversation */}
        <Box flexDirection="row" gap={2}>
          <Text bold color={s.focused ? USER : undefined}>
            {s.focused ? '●' : '○'} voice {word}
          </Text>
          {conversing && (
            <Button
              key="pane-mute"
              label={s.muted ? 'unmute' : 'mute'}
              plain
              onPress={() => ctl($, s.muted ? 'unmute' : 'mute')}
            />
          )}
          {conversing && (
            <Button
              key="pane-voice"
              label={s.voiceOff ? 'voice on' : 'voice off'}
              plain
              onPress={() => ctl($, s.voiceOff ? 'voice-on' : 'voice-off')}
            />
          )}
          {s.connected && (
            <Button
              key="pane-power"
              label={conversing ? 'stop' : 'start'}
              plain
              onPress={() => ctl($, conversing ? 'off' : 'on')}
            />
          )}
          <Button key="pane-close" label="close" plain onPress={() => togglePane($)} />
        </Box>
        {header('sessions', 'Talking to', focusedName ? folder(focusedName.cwd) : 'nobody')}
        {p.open === 'sessions' && (
          <Box flexDirection="column">
            {here && (
              <Box flexDirection="row" gap={1}>
                <Text>
                  {' '}
                  {here.focused ? '●' : '○'} {folder(here.cwd)} (this one)
                </Text>
                {!here.focused && (
                  <Button
                    key="attach"
                    label="talk here"
                    plain
                    onPress={() => talkTo($, live.session, true)}
                  />
                )}
              </Box>
            )}
            {!here && s.connected && (
              // talk attaches this session if parlard does not know it yet, then focuses it
              <Button key="attach" label="  talk here" plain onPress={() => talkTo($, live.session, true)} />
            )}
            {others.map(o => (
              <Box flexDirection="row" gap={1}>
                <Text dimColor={!o.focused}>
                  {'  '}
                  {o.focused ? '●' : '○'} {folder(o.cwd)} {o.harness}
                </Text>
                {!o.focused && (
                  <Button
                    key={`focus-${o.session}`}
                    label="talk there"
                    plain
                    onPress={() => talkTo($, o.session, false)}
                  />
                )}
              </Box>
            ))}
          </Box>
        )}
        {p.devices && header('input', 'Mic', current(inputs))}
        {p.open === 'input' && <Box flexDirection="column">{inputs.map(d => pick('input', d))}</Box>}
        {p.devices && header('output', 'Speaker', current(outputs))}
        {p.open === 'output' && <Box flexDirection="column">{outputs.map(d => pick('output', d))}</Box>}
        <Box flexDirection="column" marginTop={1}>
          {p.history.length === 0 && <Text dimColor>Nothing said yet.</Text>}
          {p.history.map(l => (
            <Text color={l.who === 'you' ? USER : AGENT} wrap="wrap">
              {l.who} ▸ {l.text}
            </Text>
          ))}
        </Box>
      </Box>
    )
  })

  on('prompt.submit', async ($, e, next) => {
    // typing here takes focus; show it without waiting for the poll
    const r = await next(e)
    void refreshFocus($).catch(quiet)
    return r
  })

  // while a turn runs and nobody talks: a voice mark and the buttons after Claude's own spinner.
  // The spinner's row takes no keys, so its buttons are for the pointer and carry no hotkeys;
  // /parlar opens the pane for the keyboard
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    const s = await read($, strip)
    const spinner = await next(e)
    if (!s.connected || s.phase === 'stopped' || TALKING.has(s.phase)) return spinner
    const { Box, Button, Text } = $.ui.resolve(e)
    return (
      // the engine's spinner opens with a blank row and may end with a tip: the controls sit on its
      // second row, the spinner's own text
      <Box flexDirection="row" gap={2}>
        {spinner}
        <Box flexDirection="row" gap={1} flexShrink={0} marginTop={1}>
          <Text color={s.muted ? undefined : AGENT} dimColor>
            {s.focused ? '●' : '○'} {s.muted ? 'mic muted' : 'voice'}
          </Text>
          {!s.focused && (
            <Button
              key="spin-focus"
              label="talk here"
              plain
              onPress={() => ctl($, 'talk', '--session', live.session)}
            />
          )}
          <Button
            key="spin-mute"
            label={s.muted ? 'unmute' : 'mute'}
            plain
            onPress={() => ctl($, s.muted ? 'unmute' : 'mute')}
          />
          <Button key="spin-stop" label="stop" plain onPress={() => ctl($, 'off')} />
          <Button
            key="spin-pane"
            label={s.paneOpen ? 'close pane' : 'pane'}
            plain
            onPress={() => togglePane($)}
          />
        </Box>
      </Box>
    )
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const s = await read($, strip)
    if (e.props.hasSurvey || !s.connected || s.phase === 'stopped') return next(e)
    const { Box, Button, Text } = $.ui.resolve(e)
    // whatever else the band holds stays, under the strip
    const below = await next(e)

    const talking = s.phase === 'speaking' ? AGENT : USER
    const color = s.flare ? 'red' : s.muted ? undefined : s.phase === 'working' ? AGENT : talking
    const word = s.muted ? 'mic muted' : WORDS[s.phase]
    const metering = s.phase === 'listening' || s.phase === 'interrupting' || s.phase === 'speaking'
    const who = s.caption?.who === 'user' ? 'you' : s.caption?.who === 'parlar' ? 'parlar' : 'agent'
    // the engine draws its collapse mark in the last columns
    const width = Math.max(20, e.props.bodyColumns - 4)
    const fit = fits(width, s, metering)
    // while a turn runs and nobody talks, the spinner line carries the voice and its buttons
    if (!metering && e.props.isWorking) return below

    return (
      <Box flexDirection="column">
        <Box flexDirection="row" gap={1} width={width}>
          {/* fixed widths and no wrapping: the strip stays one line, and its parts do not shift
              as the phase and the meter change */}
          <Box flexShrink={0}>
            <Text color={color} dimColor={s.muted || !s.focused} bold={s.focused} wrap="truncate-end">
              {s.focused ? '●' : '○'} voice {word.padEnd(WORD_WIDTH)}
            </Text>
          </Box>
          {fit.meter && (
            <Box flexShrink={0}>
              <Text color={talking} wrap="truncate-end">
                {meter(s.levels).padEnd(METER)}
              </Text>
            </Box>
          )}
          {fit.notFocused && (
            <Box flexShrink={0}>
              <Text dimColor wrap="truncate-end">
                not focused here
              </Text>
            </Box>
          )}
          {fit.captionsOnly && (
            <Box flexShrink={0}>
              <Text dimColor wrap="truncate-end">
                captions only
              </Text>
            </Box>
          )}
          {/* the caption takes what is left; a long one keeps its last words */}
          <Box flexGrow={1} flexShrink={1} minWidth={0}>
            {s.focused && s.caption && (
              <Text dimColor wrap="truncate-start">
                {who}: {s.caption.text}
              </Text>
            )}
          </Box>
          <Box flexShrink={0} gap={1}>
            {!s.focused && (
              // talk attaches a session that started before parlard, which focus alone cannot
              <Button
                key="focus"
                label="talk here"
                hotkey="t"
                plain
                onPress={() => ctl($, 'talk', '--session', live.session)}
              />
            )}
            <Button
              key="mute"
              label={s.muted ? 'unmute' : 'mute'}
              hotkey="m"
              plain
              onPress={() => ctl($, s.muted ? 'unmute' : 'mute')}
            />
            {fit.voice && (
              <Button
                key="voice"
                label={s.voiceOff ? 'voice on' : 'voice off'}
                hotkey="v"
                plain
                onPress={() => ctl($, s.voiceOff ? 'voice-on' : 'voice-off')}
              />
            )}
            <Button key="stop" label="stop" hotkey="s" plain onPress={() => ctl($, 'off')} />
            {fit.pane && (
              <Button
                key="pane"
                label={s.paneOpen ? 'close pane' : 'pane'}
                hotkey="p"
                plain
                onPress={() => togglePane($)}
              />
            )}
          </Box>
        </Box>
        {below}
      </Box>
    )
  })
}

files.hooks/rows.tsx:
// The spoken exchange in the transcript: each say call draws as a "parlar" line where the call
// sits, and each utterance as a "you" line on the row that delivered it (the voice wake row, or
// the tool call whose hook passed it on). Without this module the command hooks print the same
// lines as hook messages at the next tool call; PARLAR_ROWS, set in strip.tsx's session.start, tells
// them to leave those lines here.
// ctrl+o shows the wake rows and say groups as the engine draws them.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, On } from 'claude-code'

import type { Rows } from '../types'

export const USER = '#5fafff'
export const AGENT = '#ffaf00'

const SAY = 'mcp__plugin_parlar_parlar__say'
// what format::utterances and the wake message in hooks.json write
const WAKE = 'The user spoke to you by voice:'
const ACTIVATED = 'Voice mode is on.'
// how mcp.rs starts a say result that was not spoken
const NOT_SPOKEN = ['Not spoken', 'Voice mode is off']
// what mcp.rs and hook.rs put ahead of utterances in a tool result: any other tool's output is
// the tool's own, even when it quotes a delivery
const RESULT_CUES = ['The user said meanwhile:', 'The user asked you to stop']
// rows kept per session; older ones fall back to the engine's drawing
const KEEP = 300

const rows = atom({ plugin: 'parlar', key: 'rows' } as const, { wakes: {}, calls: {} } as Rows)

// the tool call a later PostToolUse context row belongs to: the last result appended
const last = { call: '' }

/** The utterances a delivery carries, cleaned of the reminder and the notes around them. */
export function heardIn(text: string): string[] {
  const out: string[] = []
  for (const m of text.matchAll(/\[voice u\d+(?: continues u\d+)?\] ([\s\S]*?)(?=\n\[voice u|\n\(|$)/g)) {
    const lines = (m[1] ?? '').split('\n').filter(l => !l.startsWith(ACTIVATED))
    const said = lines.join(' ').trim()
    if (said) out.push(said)
  }
  return out
}

type Block = { type: string; text?: string; tool_use_id?: string; content?: string | Block[] }

function textOf(content: string | readonly Block[] | undefined): string {
  if (typeof content === 'string') return content
  return (content ?? [])
    .map(b => (b.type === 'text' ? (b.text ?? '') : ''))
    .filter(Boolean)
    .join('\n')
}

function keep(map: Record<string, string[]>, key: string, heard: string[]) {
  const next = { ...map, [key]: [...(map[key] ?? []), ...heard] }
  const keys = Object.keys(next)
  for (const k of keys.slice(0, Math.max(0, keys.length - KEEP))) delete next[k]
  return next
}

function remember($: EngineInterface, kind: 'wakes' | 'calls', key: string, heard: string[]) {
  return update($, rows, r => ({ ...r, [kind]: keep(r[kind], key, heard) }))
}

function sayText(input: unknown): string | undefined {
  const t = (input as { text?: unknown } | null)?.text
  return typeof t === 'string' && t.trim() ? t.trim() : undefined
}

function outputText(output: unknown): string {
  return Array.isArray(output) ? textOf(output as Block[]) : typeof output === 'string' ? output : ''
}

/** Why a say was not spoken, from its result: the first sentence of mcp.rs's note. */
function notSpoken(output: unknown): string | undefined {
  const t = outputText(output)
  if (!NOT_SPOKEN.some(n => t.startsWith(n))) return undefined
  return t.split(/(?<=\.) /)[0]?.replace(/\.$/, '')
}

/** The utterances a tool result passed on, after the cue parlar writes ahead of them. */
function heardInResult(text: string): string[] {
  const cue = RESULT_CUES.map(c => text.indexOf(c)).find(i => i >= 0)
  return cue === undefined ? [] : heardIn(text.slice(cue))
}

type Call = { tool_use_id?: string; tool: string; input: unknown; output?: unknown }
type Line = { who: 'you' | 'parlar' | 'note'; text: string; note?: string }

/** The lines one tool call adds: what it spoke, then what the user said that it passed on. */
function linesOf(c: Call, r: Rows): Line[] {
  const out: Line[] = []
  if (c.tool === SAY) {
    const t = sayText(c.input)
    if (t) out.push({ who: 'parlar', text: t, note: notSpoken(c.output) })
  }
  // a say result or a refused call's reason carries them in the row's own output; a PostToolUse
  // context row only in what session.append noted
  const heard = [...heardInResult(outputText(c.output)), ...(r.calls[c.tool_use_id ?? ''] ?? [])]
  for (const h of heard) out.push({ who: 'you', text: h })
  // parlar's own answer while the call ran: a system note, not the agent speaking
  for (const n of r.notes?.[c.tool_use_id ?? ''] ?? []) out.push({ who: 'note', text: n })
  return out
}

type Appended = { door: string; origin: { kind: string }; uuid: string; message: unknown; agentId?: string }
type Note = { kind: 'wakes' | 'calls'; key: string; heard: string[] }

/** What one appended row tells about which row delivered which utterances. */
export function notesOf(e: Appended, lastCall: string): { notes: Note[]; lastCall: string } {
  const m = e.message as { name?: string; content?: string | Block[] }
  const notes: Note[] = []
  // speech goes to the main thread; a subagent's rows would move lastCall off it
  if (e.agentId) return { notes, lastCall }
  if (e.door === 'prompt' && e.origin.kind === 'task-notification') {
    const text = textOf(m.content)
    if (text.includes(WAKE))
      notes.push({ kind: 'wakes', key: e.uuid, heard: heardIn(text.slice(text.indexOf(WAKE))) })
  }
  // a tool result's own utterances are read from the row's output; here it only marks the call
  // a following PostToolUse context row belongs to
  if (e.door === 'tool-result' && Array.isArray(m.content)) {
    for (const b of m.content) if (b.type === 'tool_result' && b.tool_use_id) lastCall = b.tool_use_id
  }
  if (e.door === 'hook-context' && m.name === 'hook_additional_context') {
    notes.push({ kind: 'calls', key: lastCall, heard: heardIn(textOf(m.content)) })
  }
  return { notes: notes.filter(n => n.key && n.heard.length > 0), lastCall }
}

type TextOf = ReturnType<EngineInterface['ui']['resolve']>['Text']

/** One drawn line: the person in blue, the agent in amber, parlar's own notes dim and plain. */
function drawLine(l: Line, Text: TextOf) {
  if (l.who === 'note') {
    return (
      <Text dimColor italic>
        · {l.text}
      </Text>
    )
  }
  return (
    <Text color={l.who === 'you' ? USER : AGENT} dimColor={l.note !== undefined}>
      {l.who} ▸ {l.text}
      {l.note ? ` (${l.note})` : ''}
    </Text>
  )
}

/** Keep parlar's note on the tool call it answered during, for that call's row. */
export function withNote(r: Rows, call: string, text: string): Rows {
  const notes = keep(r.notes ?? {}, call, [text])
  return { ...r, notes }
}

export function registerRows(on: On) {
  on('session.append', async ($, e, next) => {
    const { notes, lastCall } = notesOf(e, last.call)
    last.call = lastCall
    for (const n of notes) await remember($, n.kind, n.key, n.heard)
    return next(e)
  })

  on('ui.render', { component: 'UserMessage' }, async ($, e, next) => {
    if (e.props.isExpanded || e.props.origin.kind !== 'task-notification') return next(e)
    const heard = (await read($, rows)).wakes[e.requestId ?? '']
    if (!heard) return next(e)
    const { Box, Text } = $.ui.resolve(e)
    return (
      <Box flexDirection="column">
        {heard.map(said => (
          <Text color={USER}>you ▸ {said}</Text>
        ))}
      </Box>
    )
  })

  on('ui.render', { component: 'ToolGroup' }, async ($, e, next) => {
    if (e.props.isExpanded) return next(e)
    const r = await read($, rows)
    const lines = e.props.calls.flatMap(c => linesOf(c, r))
    if (lines.length === 0) return next(e)
    const { Box, Text } = $.ui.resolve(e)
    // a group of say calls alone is the lines; any other call keeps the engine's summary above
    const onlySay = e.props.calls.every(c => c.tool === SAY)
    const above = onlySay ? null : await next(e)
    return (
      <Box flexDirection="column">
        {above}
        {lines.map(l => drawLine(l, Text))}
      </Box>
    )
  })

  on('ui.render', { component: 'ToolUse' }, async ($, e, next) => {
    const lines = linesOf(e.props, await read($, rows))
    if (lines.length === 0) return next(e)
    const { Box, Text } = $.ui.resolve(e)
    const above = e.props.tool === SAY ? null : await next(e)
    return (
      <Box flexDirection="column">
        {above}
        {lines.map(l => drawLine(l, Text))}
      </Box>
    )
  })

  // a say call's result is "Said." plus what it passed on, which its row already shows
  on('ui.render', { component: 'ToolResult' }, async ($, e, next) => {
    if (e.props.tool !== SAY || e.props.isErrored) return next(e)
    const { Box } = $.ui.resolve(e)
    return <Box />
  })
}

